import{_ as p,a0 as o,w as d,s as u,I as s,x as l,a1 as a,A as e,ao as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"LXDE、Xfce 及 MATE 桌面环境下的又一系统监视器应用：Multiload-ng | LCTT x X-CMD","titleTemplate":false,"description":"LXDE、Xfce 及 MATE 桌面环境下的又一系统监视器应用：Multiload-ng | LCTT (201609) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"LXDE、Xfce 及 MATE 桌面环境下的又一系统监视器应用：Multiload-ng | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"LXDE、Xfce 及 MATE 桌面环境下的又一系统监视器应用：Multiload-ng | LCTT (201609) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201609/20160815 Alternative System Monitor Applet For LXDE  Xfce  And MATE - Multiload-ng","title":"LXDE、Xfce 及 MATE 桌面环境下的又一系统监视器应用：Multiload-ng","tag":"201609","desc":""},"relativePath":"201609/20160815 Alternative System Monitor Applet For LXDE  Xfce  And MATE - Multiload-ng.md","filePath":"[post].md"}'),g={name:"201609/20160815 Alternative System Monitor Applet For LXDE  Xfce  And MATE - Multiload-ng.md"};function r(A,t,b,h,m,f){const i=o("Link");return d(),u("div",null,[t[21]||(t[21]=s("h1",{id:"lxde、xfce-及-mate-桌面环境下的又一系统监视器应用-multiload-ng",tabindex:"-1"},[l("LXDE、Xfce 及 MATE 桌面环境下的又一系统监视器应用：Multiload-ng "),s("a",{class:"header-anchor",href:"#lxde、xfce-及-mate-桌面环境下的又一系统监视器应用-multiload-ng","aria-label":"Permalink to “LXDE、Xfce 及 MATE 桌面环境下的又一系统监视器应用：Multiload-ng”"},"​")],-1)),s("p",null,[a(i,{href:"https://github.com/udda/multiload-ng"},{default:e(()=>[...t[0]||(t[0]=[l("Multiload-ng",-1)])]),_:1}),t[1]||(t[1]=l(" 是一个 GTK2 图形化系统监视器应用，可集成到 Xfce、LXDE 及 MATE 的桌面面板中， 它 fork 自原来的 GNOME Multiload 应用。它也可以运行在一个独立的窗口中。",-1))]),t[22]||(t[22]=n('<p><img src="https://2.bp.blogspot.com/-U8CFzhSPJho/V7GigDbcLWI/AAAAAAAAYS0/pJMM6Rt5-HkbKljmxzP4-v0oGGxjvH8AgCLcB/s1600/multiload-ng-lxde.png" alt=""></p><p>Multiload-ng 的特点有：</p><ul><li>支持以下资源的图形块： CPU，内存，网络，交换空间，平均负载，磁盘以及温度；</li><li>高度可定制；</li><li>支持配色方案；</li><li>自动适应容器（面板或窗口）的改变；</li><li>极低的 CPU 和内存占用；</li><li>提供基本或详细的提示信息；</li><li>可自定义双击触发的动作。</li></ul><p>相比于原来的 Multiload 应用，Multiload-ng 含有一个额外的图形块（温度），以及更多独立的图形自定义选项，例如独立的边框颜色，支持配色方案，可根据自定义的动作对鼠标的点击做出反应，图形块的方向可以被设定为与面板的方向无关。</p><p>它也可以运行在一个独立的窗口中，而不需要面板：</p><p><img src="https://1.bp.blogspot.com/-hHoipwFlHrg/V7Gw2s107zI/AAAAAAAAYTQ/fS5OtiL7VvwDEzr6qO_gdEA_qB9YvJa5gCLcB/s400/multiload-ng-standalone.png" alt=""></p><p>另外，它的 GitHub page 上说还会带来更多的图形块支持。</p><p>下图展示的是在带有一个垂直面板的 Xubuntu 16.04 中，该应用分别处于水平和垂直方向的效果：</p><p><img src="https://3.bp.blogspot.com/-xa0OML8T-lg/V7Gixksbt8I/AAAAAAAAYS4/Jxo-MukDh3sYlOOk9A1YGtARmte490g8ACLcB/s400/multiload-ng-xfce-horizontal.png" alt=""></p><p><img src="https://1.bp.blogspot.com/-WAD5MdDObD8/V7GixgVU0DI/AAAAAAAAYS8/uMhHJri1GJccRWvmf_tZkYeenVdxiENQwCLcB/s400/multiload-ng-xfce-vertical.png" alt=""></p><p>这个应用的偏好设置窗口虽然不是非常好看，但是有计划去改进它：</p><p><img src="https://2.bp.blogspot.com/-P-ophDpc-gI/V7Gi_54b7JI/AAAAAAAAYTA/AHQck_JF_RcwZ1KbgHbaO2JRt24ZZdO3gCLcB/s320/multiload-ng-preferences.png" alt=""></p><p>Multiload-ng 当前使用的是 GTK2，所以它不能在构建自 GTK3 下的 Xfce 或 MATE 桌面环境（面板）下工作。</p><p>对于 Ubuntu 系统而言，只有 Ubuntu MATE 16.10 使用 GTK3。但是鉴于 MATE 的系统监视器应用也是 Multiload GNOME 的一个分支，所以它们大多数的功能相同（除了 Multiload-ng 提供的额外自定义选项和温度图形块）。</p>',14)),s("p",null,[t[3]||(t[3]=l("该应用的",-1)),a(i,{href:"https://github.com/udda/multiload-ng/wiki/Wishlist"},{default:e(()=>[...t[2]||(t[2]=[l("愿望清单",-1)])]),_:1}),t[4]||(t[4]=l(" 中提及到了计划支持 GTK3 的集成以及各种各样的改进，例如温度块资料的更多来源，能够显示十进制（KB、MB、GB……）或二进制（KiB、MiB、GiB……）单位等等。",-1))]),t[23]||(t[23]=n(`<h3 id="安装-multiload-ng" tabindex="-1">安装 Multiload-ng <a class="header-anchor" href="#安装-multiload-ng" aria-label="Permalink to “安装 Multiload-ng”">​</a></h3><p>请注意因为依赖的关系， Multiload-ng 不能在 Lubuntu 14.04 上构建。</p><p>Multiload-ng 可在 WebUpd8 的主 PPA （针对 Ubuntu 14.04 - 16.04 / Linux Mint 17.x 和 18）中获取到。可以使用下面的命令来添加 PPA 并更新软件源：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository ppa:nilarimogard/webupd8</span></span>
<span class="line"><span>sudo apt update</span></span></code></pre></div><p>然后可以使用下面的命令来安装这个应用：</p><ul><li>对于 LXDE (Lubuntu)：</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install lxpanel-multiload-ng-plugin</span></span></code></pre></div><ul><li>对于 Xfce (Xubuntu，Linux Mint Xfce)：</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install xfce4-multiload-ng-plugin</span></span></code></pre></div><ul><li>对于 MATE (Ubuntu MATE，Linux Mint MATE)：</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install mate-multiload-ng-applet</span></span></code></pre></div><ul><li>独立安装 (不需要集成到面板)：</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install multiload-ng-standalone</span></span></code></pre></div><p>一旦安装完毕，便可以像其他应用那样添加到桌面面板中了。需要注意的是在 LXDE 中，Multiload-ng 不能马上出现在面板清单中，除非重新启动面板。你可以通过重启会话（登出后再登录）或者使用下面的命令来重启面板：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lxpanelctl restart</span></span></code></pre></div><p>独立的 Multiload-ng 应用可以像其他正常应用那样从菜单中启动。</p>`,16)),s("p",null,[t[6]||(t[6]=l("如果要下载源码或报告 bug 等，请看 Multiload-ng 的 ",-1)),a(i,{href:"https://github.com/udda/multiload-ng"},{default:e(()=>[...t[5]||(t[5]=[l("GitHub page",-1)])]),_:1}),t[7]||(t[7]=l("。",-1))]),t[24]||(t[24]=s("hr",null,null,-1)),s("p",null,[t[9]||(t[9]=l("via: ",-1)),a(i,{href:"http://www.webupd8.org/2016/08/alternative-system-monitor-applet-for.html"},{default:e(()=>[...t[8]||(t[8]=[l("http://www.webupd8.org/2016/08/alternative-system-monitor-applet-for.html",-1)])]),_:1})]),s("p",null,[t[13]||(t[13]=l("作者：",-1)),a(i,{href:"http://www.webupd8.org/p/about.html"},{default:e(()=>[...t[10]||(t[10]=[l("Andrew",-1)])]),_:1}),t[14]||(t[14]=l(" 译者：",-1)),a(i,{href:"https://github.com/FSSlc"},{default:e(()=>[...t[11]||(t[11]=[l("FSSlc",-1)])]),_:1}),t[15]||(t[15]=l(" 校对：",-1)),a(i,{href:"https://github.com/wxy"},{default:e(()=>[...t[12]||(t[12]=[l("wxy",-1)])]),_:1})]),s("p",null,[t[18]||(t[18]=l("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[16]||(t[16]=[l("LCTT",-1)])]),_:1}),t[19]||(t[19]=l(" 原创编译，",-1)),a(i,{href:"https://linux.cn/"},{default:e(()=>[...t[17]||(t[17]=[l("Linux中国",-1)])]),_:1}),t[20]||(t[20]=l(" 荣誉推出",-1))])])}const x=p(g,[["render",r]]);export{T as __pageData,x as default};
